import {PLANET} from './planet.js';
export function drawOrbit(canvas,o,{detail=false}={}){const c=canvas.getContext('2d'),w=canvas.width,m=w/2,bound=Number.isFinite(o.apoapsis),limit=Math.max(o.radius,PLANET.radius*1.2,bound?PLANET.radius+o.apoapsis:PLANET.radius*4),scale=(m-(detail?52:12))/limit;c.clearRect(0,0,w,w);const circle=(r,color)=>{c.beginPath();c.arc(m,m,r*scale,0,2*Math.PI);c.fillStyle=color;c.fill();};circle(PLANET.radius+PLANET.atmosphereTop,'#3b748a');circle(PLANET.radius,'#516e63');const eccentric=o.eccentricity>1e-4,x=eccentric?o.evec.clone().normalize():o.r.clone().normalize(),y=o.normal.clone().cross(x).normalize();if(o.normal.lengthSq()>.5){c.strokeStyle='#efb067';c.lineWidth=detail?2:1.5;let prior=null;for(let i=0;i<=720;i++){const a=i*Math.PI/360,den=1+o.eccentricity*Math.cos(a),r=o.p/den;if(den<=0||r>limit*1.2){prior=null;continue;}const px=m+r*Math.cos(a)*scale,py=m-r*Math.sin(a)*scale;if(prior){c.beginPath();c.setLineDash(r<PLANET.radius?[3,4]:[]);c.strokeStyle=r<PLANET.radius?'#fa7370':'#efb067';c.moveTo(...prior);c.lineTo(px,py);c.stroke();}prior=[px,py];}c.setLineDash([]);}const px=m+o.r.dot(x)*scale,py=m-o.r.dot(y)*scale;c.beginPath();c.arc(px,py,detail?5:3,0,Math.PI*2);c.fillStyle='#fff';c.fill();if(detail){c.font='13px sans-serif';c.textAlign='center';c.fillStyle='#d2e4e8';c.fillText('半径600 km / 大気70 km',m,m+5);c.fillStyle='#fff';c.fillText('機体',px,py-14);if(eccentric&&o.normal.lengthSq()>.5){for(const [label,r,sign]of [['Pe',PLANET.radius+o.periapsis,1],['Ap',PLANET.radius+o.apoapsis,-1]]){if(!Number.isFinite(r)||r>limit*1.2)continue;const ax=m+sign*r*scale;c.fillStyle=r<PLANET.radius?'#fa7370':'#7de6ef';c.beginPath();c.arc(ax,m,4,0,2*Math.PI);c.fill();c.fillText(label,ax,m+20);}}}}
